expect(splitCents(1000, 1)).toEqual([1000]);  // Mock toEqual for deep check

// --- Input validation ---
try {
    splitCents(-100, 3);
} catch (e) {
    strictEqual(e.constructor, RangeError, "Correctly rejects negative total");
}

try {
    splitCents(1000, 1001);
} catch (e) {
    strictEqual(e.constructor, RangeError, "Correctly rejects count > 1000");
}

